// Global injected by vite.config.ts's `define` — a per-build id (Date.now().toString(36))
// used to version the service-worker registration URL and cache name (see main.tsx and
// public/sw.js). Not present in `npm run dev` transforms of files that don't reference
// it, but always substituted by esbuild/rollup wherever it's used in bundled source.
declare const __BUILD_ID__: string;
